  ('muradins-guardian', 'Muradin''s Guardian', 'Recipe', 500, ARRAY['+6 Strength', '+6 All Stats', '+5 Damage', '+600 Maximum Health', 'Avatar (passive): damage which would kill bearer cause him to be healed for 40% health instead and increase his armor by amount of 0.5% maximum health for 15 sec. Also causes enemy melee units that attack bearer to reduce their movement speed by 40% and attack speed by 20% for 5 sec.', 'Cooldown: 90 sec']::text[], 'Grants +6 Strength, +6 all stats, +5 damage, and +600 maximum health. Avatar causes lethal damage to heal the bearer for 40% health instead and increases armor by 0.5% maximum health for 15 seconds. Enemy melee attackers have their movement speed reduced by 40% and attack speed reduced by 20% for 5 seconds. Cooldown: 90 seconds.', null, '{"allStats":6,"strength":12,"agility":6,"intelligence":6,"damage":5,"maxHealth":600,"avatarHealPercent":40,"avatarArmorFromMaxHealthPercent":0.5,"avatarDuration":15,"meleeAttackerMovementSpeedReductionPercent":40,"meleeAttackerAttackSpeedReductionPercent":20,"meleeAttackerDebuffDuration":5,"avatarCooldown":90}'::jsonb, '[{"itemId":"maul-of-strength","quantity":1},{"itemId":"crown-of-kings","quantity":1},{"itemId":"periapt-of-health","quantity":1}]'::jsonb, ARRAY['tomb-of-relics']::text[], '/icons/BTNHelmOfValor.png'),
