  ('hood-of-cunning', 'Hood of Cunning', 'Recipe', 750, ARRAY['+10 Agility', '+6 All Stats', '+6 Armor', 'Anti-magic Shell (passive): reduces spell damage taken by 20% (+0.2% for each 1% Evasion chance) and spell damage which would kill bearer cause him to be shielded instead, absorbing 500 (+5 for each 1% Evasion chance) spell damage for next 15 sec.', 'Cooldown: 60 sec']::text[], 'Grants +10 Agility, +6 all stats, and +6 armor. Anti-magic Shell reduces spell damage taken and can shield the bearer from lethal spell damage. Cooldown: 60 seconds.', null, '{"allStats":6,"strength":6,"agility":16,"intelligence":6,"armor":6,"spellDamageTakenReductionPercent":20,"spellDamageTakenReductionPerEvasionPercent":0.2,"lethalSpellShieldAbsorb":500,"lethalSpellShieldAbsorbPerEvasionPercent":5,"lethalSpellShieldDuration":15,"antiMagicShellCooldown":60}'::jsonb, '[{"itemId":"boots-of-quelthalas","quantity":1},{"itemId":"crown-of-kings","quantity":1},{"itemId":"ring-of-protection-5","quantity":1}]'::jsonb, ARRAY['voodoo-lounge']::text[], '/icons/BTNHoodOfCunning.png'),
