  ('helmet-of-awakening', 'Helmet of Awakening', 'Recipe', 1000, ARRAY['+4 All Stats', '+4 Armor', '+700 Maximum Health', '+1% Maximum Health Regeneration', 'Doesn''t stack', 'Fortitude (passive): increases maximum health by 5%', 'Doesn''t stack']::text[], 'Grants +4 all stats, +4 armor, +700 maximum health, and +1% maximum health regeneration. Fortitude increases maximum health by 5%. Doesn''t stack.', null, '{"allStats":4,"strength":4,"agility":4,"intelligence":4,"armor":4,"maxHealth":700,"maxHealthRegenerationPercent":1,"maxHealthIncreasePercent":5}'::jsonb, '[{"itemId":"bracer-of-protection","quantity":1},{"itemId":"periapt-of-health","quantity":1},{"itemId":"periapt-of-vitality","quantity":1}]'::jsonb, ARRAY['voodoo-lounge']::text[], '/icons/BTNArmorGolem.png'),
  ('hammer-of-fright', 'Hammer of Fright', 'Recipe', 625, ARRAY['+6 Strength', '+5 Damage', '+7 Armor', '+500 Maximum Health', 'Fear (passive): attacks reduce target''s and enemy units'' around within 225 range damage by 15% for 2 sec.', 'Doesn''t stack']::text[], 'Grants +6 Strength, +5 damage, +7 armor, and +500 maximum health. Fear reduces the damage of the target and nearby enemy units by 15% for 2 seconds. Doesn''t stack.', 225, '{"strength":6,"damage":5,"armor":7,"maxHealth":500,"fearDamageReductionPercent":15,"fearRange":225,"fearDuration":2}'::jsonb, '[{"itemId":"maul-of-strength","quantity":1},{"itemId":"periapt-of-health","quantity":1},{"itemId":"ring-of-protection-5","quantity":1}]'::jsonb, ARRAY['voodoo-lounge']::text[], '/icons/BTNDivineShieldOff.png'),
  ('enchanted-shield', 'Enchanted Shield', 'Recipe', 650, ARRAY['+10 Intelligence', '+6 All Stats', '+250 Maximum Mana', 'Energy Shield (active): absorbs 20% damage taken draining mana equal to 50% of damage absorbed. Absorbs 40% if under 50% health. Absorbs 60% if damage taken is lethal.']::text[], 'Grants +10 Intelligence, +6 all stats, and +250 maximum mana. Energy Shield absorbs part of incoming damage by draining mana equal to 50% of damage absorbed, with stronger absorption while under 50% health or against lethal damage.', null, '{"allStats":6,"strength":6,"agility":6,"intelligence":16,"maxMana":250,"energyShieldDamageAbsorbPercent":20,"energyShieldManaDrainPercentOfDamageAbsorbed":50,"lowHealthDamageAbsorbPercent":40,"lowHealthThresholdPercent":50,"lethalDamageAbsorbPercent":60}'::jsonb, '[{"itemId":"robe-of-the-magi","quantity":1},{"itemId":"crown-of-kings","quantity":1},{"itemId":"pendant-of-mana","quantity":1}]'::jsonb, ARRAY['voodoo-lounge']::text[], '/icons/BTNThoriumArmor.png'),
  ('khadgars-spellbook', 'Khadgar''s Spellbook', 'Recipe', 725, ARRAY['+8 Intelligence', '+6 All Stats', '+350 Maximum Mana', '+50% Mana Regeneration', 'Amplify Magic Field (active): places a field dealing 2% maximum mana (150 range), 1.5% maximum mana (225 range), 1% maximum mana (300 range) spell damage per sec to enemy units, reduces their movement speed by 20% and increases spell damage taken by 33% for 8 sec.', 'Mana cost: 10% maximum mana', 'Cooldown: 30 sec', 'Doesn''t stack with Aura of Decay']::text[], 'Grants +8 Intelligence, +6 all stats, +350 maximum mana, and +50% mana regeneration. Amplify Magic Field deals spell damage based on maximum mana, slows enemies, and increases spell damage taken for 8 seconds. Mana cost: 10% maximum mana. Cooldown: 30 seconds. Doesn''t stack with Aura of Decay.', 300, '{"allStats":6,"strength":6,"agility":6,"intelligence":14,"maxMana":350,"manaRegenerationPercent":50,"amplifyMagicFieldInnerDamageMaxManaPercent":2,"amplifyMagicFieldInnerRange":150,"amplifyMagicFieldMiddleDamageMaxManaPercent":1.5,"amplifyMagicFieldMiddleRange":225,"amplifyMagicFieldOuterDamageMaxManaPercent":1,"amplifyMagicFieldOuterRange":300,"movementSpeedReductionPercent":20,"spellDamageTakenIncreasePercent":33,"amplifyMagicFieldDuration":8,"manaCostMaxManaPercent":10,"cooldown":30}'::jsonb, '[{"itemId":"ancient-figurine","quantity":1},{"itemId":"crown-of-kings","quantity":1},{"itemId":"pendant-of-mana","quantity":1}]'::jsonb, ARRAY['voodoo-lounge']::text[], '/icons/BTNSorceressAdept.png'),
