-- Seed game data from backend/src/main/resources/data JSON files.
-- Keep future game-data edits in new migrations instead of changing this file after it is applied.

on conflict (id) do update set
  name = excluded.name;

on conflict (id) do update set
  name = excluded.name,
  hero_class = excluded.hero_class,
  roles = excluded.roles,
  icon_url = excluded.icon_url;

on conflict (id) do update set
  name = excluded.name,
  item_class = excluded.item_class,
  price = excluded.price,
  bonuses = excluded.bonuses,
  description = excluded.description,
  "range" = excluded."range",
  stats = excluded.stats,
  requirements = excluded.requirements,
  shop_ids = excluded.shop_ids,
  icon_url = excluded.icon_url;
